To create a program that can perform the activities or behaviors associated with each of the two realistic objects in the image, we need to identify what those objects are and what they represent in the context of changing patient records in a hospital's system.

1. **Apple**: The apple in the image is likely a metaphor for data or information. In the context of a hospital's system, an apple could represent patient records or medical data.

2. **Man with a mask**: The man with a mask could represent a hacker or an unauthorized user attempting to access or modify patient records.

Given these interpretations, here are two programs that could be created:

### Program 1: Data Protection System
This program would focus on protecting patient records from unauthorized access and modification.

```python
import hashlib
import os

class DataProtectionSystem:
    def __init__(self, password):
        self.password = password
        self.patient_records = {}

    def add_patient_record(self, patient_id, record):
        hashed_password = hashlib.sha256(self.password.encode()).hexdigest()
        if hashed_password in self.patient_records:
            self.patient_records[hashed_password].append((patient_id, record))
        else:
            self.patient_records[hashed_password] = [(patient_id, record)]

    def remove_patient_record(self, patient_id):
        hashed_password = hashlib.sha256(self.password.encode()).hexdigest()
        if hashed_password in self.patient_records:
            for record in self.patient_records[hashed_password]:
                if record[0] == patient_id:
                    self.patient_records[hashed_password].remove(record)
                    return True
        return False

    def update_patient_record(self, patient_id, new_record):
        hashed_password = hashlib.sha256(self.password.encode()).hexdigest()
        if hashed_password in self.patient_records:
            for record in self.patient_records[hashed_password]:
                if record[0] == patient_id:
                    self.patient_records[hashed_password].remove(record)
                    self.patient_records[hashed_password].append((patient_id, new_record))
                    return True
        return False

    def get_patient_record(self, patient_id):
        hashed_password = hashlib.sha256(self.password.encode()).hexdigest()
        if hashed_password in self.patient_records:
            for record in self.patient_records[hashed_password]:
                if record[0] == patient_id:
                    return record[1]
        return None

    def __str__(self):
        return f"Data Protection System with {len(self.patient_records)} records."

# Example usage
system = DataProtectionSystem("securepassword")
system.add_patient_record(1, "Record 1")
system.add_patient_record(2, "Record 2")
print(system)
system.update_patient_record(1, "Updated Record 1")
print(system)
system.remove_patient_record(2)
print(system)
```

### Program 2: Unauthorized Access Detection System
This program would focus on detecting and preventing unauthorized access to patient records.

```python
import hashlib
import os

class UnauthorizedAccessDetectionSystem:
    def __init__(self, password):
        self.password = password
        self.access_attempts = {}

    def authenticate(self, patient_id, record):
        hashed_password = hashlib.sha256(self.password.encode()).hexdigest()
        if hashed_password in self.access_attempts:
            if self.access_attempts[hashed_password] > 3:
                return False
            else:
                self.access_attempts[hashed_password] += 1
                return True
        else:
            self.access_attempts[hashed_password] = 1
            return True

    def block_access(self, patient_id):
        hashed_password = hashlib.sha256(self.password.encode()).hexdigest()
        if hashed_password in self.access_attempts:
            self.access_attempts[hashed_password] = 0

    def __str__(self):
        return f"Unauthorized Access Detection System with {len(self.access_attempts)} attempts."

# Example usage
system = UnauthorizedAccessDetectionSystem("securepassword")
print(system.authenticate(1, "Record 1"))  # True
print(system.authenticate(1, "Record 1"))  # True
print(system.authenticate(1, "Record 1"))  # True
print(system.authenticate(1, "Record 1"))  # False (access blocked after 3 attempts)
system.block_access(1)
print(system.authenticate(1, "Record 1"))  # True (access blocked is reset)
```

