import sys
import os
import hashlib
import datetime

class PatientRecordSystem:
    def __init__(self):
        self.patient_records = {}

    def add_patient(self, patient_id, name, date_of_birth, medical_history):
        # Validate data
        if not all([name, date_of_birth, medical_history]):
            print("Invalid data. All fields are required.")
            return False
        # Add patient to records
        self.patient_records[patient_id] = {
            'name': name,
            'date_of_birth': date_of_birth,
            'medical_history': medical_history
        }
        return True

    def update_patient(self, patient_id, field, value):
        # Validate data
        if not all([patient_id, field, value]):
            print("Invalid data. All fields are required.")
            return False
        # Update patient record
        if patient_id in self.patient_records:
            self.patient_records[patient_id][field] = value
        else:
            print("Patient not found.")
            return False
        return True

    def delete_patient(self, patient_id):
        # Validate data
        if not patient_id:
            print("Invalid patient ID.")
            return False
        # Delete patient record
        if patient_id in self.patient_records:
            del self.patient_records[patient_id]
        else:
            print("Patient not found.")
            return False
        return True

    def encrypt_data(self, data):
        # Implement encryption logic
        # For simplicity, using a basic hash function
        return hashlib.sha256(data.encode()).hexdigest()

def main():
    system = PatientRecordSystem()
    while True:
        print("\nPatient Record System Menu:")
        print("1. Add Patient")
        print("2. Update Patient")
        print("3. Delete Patient")
        print("4. Exit")
        choice = input("Enter your choice: ")

        if choice == '1':
            patient_id = input("Enter patient ID: ")
            name = input("Enter patient name: ")
            date_of_birth = input("Enter date of birth (YYYY-MM-DD): ")
            medical_history = input("Enter medical history: ")
            if system.add_patient(patient_id, name, date_of_birth, medical_history):
                print("Patient added successfully.")
            else:
                print("Failed to add patient.")
        elif choice == '2':
            patient_id = input("Enter patient ID: ")
            field = input("Enter field to update (name, date_of_birth, medical_history): ")
            value = input("Enter new value: ")
            if system.update_patient(patient_id, field, value):
                print("Patient record updated successfully.")
            else:
                print("Failed to update patient record.")
        elif choice == '3':
            patient_id = input("Enter patient ID: ")
            if system.delete_patient(patient_id):
                print("Patient record deleted successfully.")
            else:
                print("Failed to delete patient record.")
